//! The VS Code workspace of a project: `build/<name>.code-workspace`, regenerated by every build, the same for every
//! platform.
//!
//! It has two folders, the NuclearLang sources (the project) and the generated app, the `dragonfly` tasks of the
//! commands the project has (build, install, run, test, check; a mobile app also watch and analyze) and the debug
//! launches of its dialect. What depends on the dialect is the dialect's data, never this file: `[[toolchain.launch]]`
//! (placeholders `{{app}}`, `{{name}}`, `{{url}}`, `{{port}}`), `[toolchain.settings]`, `[toolchain] extensions` and
//! `ready` (the line a running server prints when it answers). A breakpoint in a `.nuc` reaches the generated file
//! through the line map every build writes (the editor extension mirrors it). The errors of the `.nuc` files come from
//! the Nuclear language server, not from the tasks.

use nuclear_dialect::Dialect;
use nuclear_transpile::project::Manifest;
use serde_json::{Value, json};
use std::path::{Path, PathBuf};

pub fn workspace_path(root: &Path, m: &Manifest) -> PathBuf {
    root.join("build").join(format!("{}.code-workspace", m.name))
}

/// The port of the dialect's `url` (`http://localhost:8000` → 8000), the `{{port}}` of its commands and launches.
pub fn url_port(dialect: &Dialect) -> Option<String> {
    let url = dialect.tool("url")?;
    let rest = url.split("://").nth(1).unwrap_or(url);
    let host = rest.split('/').next().unwrap_or(rest);
    host.rsplit_once(':').map(|(_, p)| p.to_string())
}

/// `{{name}}`, `{{url}}`, `{{port}}`, `{{app}}` in every string of a launch.
fn fill(v: &Value, vars: &[(&str, String)]) -> Value {
    match v {
        Value::String(s) => Value::String(vars.iter().fold(s.clone(), |acc, (k, x)| acc.replace(&format!("{{{{{k}}}}}"), x))),
        Value::Array(a) => Value::Array(a.iter().map(|x| fill(x, vars)).collect()),
        Value::Object(o) => Value::Object(o.iter().map(|(k, x)| (k.clone(), fill(x, vars))).collect()),
        other => other.clone(),
    }
}

/// Writes the workspace (only when its content changed). `out_rel`: the generated app, relative to the project;
/// `env`: what the tasks need (a mobile app's `FLUTTER_ROOT`); `machine`: settings of this machine (the Flutter SDK).
pub fn write(
    root: &Path,
    m: &Manifest,
    dialect: &Dialect,
    out_rel: &str,
    env: serde_json::Map<String, Value>,
    machine: serde_json::Map<String, Value>,
) -> Result<(), String> {
    let mobile = m.platform.as_deref() == Some("mobile") || m.platform.is_none();
    let sources = format!("{} (.nuc)", m.name);
    let app = format!("{} (app)", m.name);
    // build/<out> relative to build/: build/app → app, build → .
    let app_path = Path::new(out_rel).strip_prefix("build").unwrap_or(Path::new(out_rel)).to_string_lossy().into_owned();
    let app_path = if app_path.is_empty() { ".".to_string() } else { app_path };
    let app_folder = format!("${{workspaceFolder:{app}}}");
    let src_folder = format!("${{workspaceFolder:{sources}}}");
    // this same binary, so the tasks work even when dragonfly is not in VS Code's PATH
    let dragonfly = std::env::current_exe().map(|p| p.display().to_string()).unwrap_or_else(|_| "dragonfly".into());
    // a background task marks its rounds; the pattern matches nothing (the language server reports the errors)
    let background = |begins: &str, ends: &str| {
        json!({
            "owner": "dragonfly",
            "pattern": { "regexp": "^\\b$" },
            "background": { "activeBegins": true, "beginsPattern": begins, "endsPattern": ends }
        })
    };
    let task = |label: &str, args: &[&str], group: Value, matcher: Option<Value>| {
        let mut t = json!({
            "label": label,
            "type": "process",
            "command": dragonfly,
            "args": args,
            "options": { "cwd": src_folder, "env": env },
            "problemMatcher": matcher.clone().unwrap_or(json!([])),
            "group": group,
        });
        if matcher.is_some() {
            t["isBackground"] = json!(true);
            t["presentation"] = json!({ "reveal": "silent", "panel": "dedicated" });
        }
        t
    };
    let mut tasks = vec![task("dragonfly: build", &["build"], json!({ "kind": "build", "isDefault": true }), None)];
    if mobile {
        // a saved .nuc is transpiled at once; the Dart extension hot reloads the generated .dart
        let mut watch = task("dragonfly: watch", &["watch"], json!("none"), Some(background("^dragonfly: transpiling", "^dragonfly: (ready|errors)")));
        watch["runOptions"] = json!({ "runOn": "folderOpen" });
        tasks.push(watch);
    }
    if dialect.tool("install").is_some() {
        tasks.push(task("dragonfly: install", &["install"], json!("none"), None));
    }
    if let Some(ready) = dialect.tool("run").and(dialect.tool("ready")) {
        // `dragonfly run` serves until stopped: a launch that needs it waits for the server's ready line
        tasks.push(task("dragonfly: run", &["run"], json!("none"), Some(background("^\\$ nuclear build", ready))));
    }
    tasks.push(task("dragonfly: test", &["test"], json!({ "kind": "test", "isDefault": true }), None));
    if mobile {
        tasks.push(task("dragonfly: test --integration", &["test", "--integration"], json!("test"), None));
        tasks.push(task("dragonfly: analyze", &["analyze"], json!("none"), None));
    }
    tasks.push(task("dragonfly: check", &["check"], json!("none"), None));
    let vars = [
        ("name", m.name.clone()),
        ("app", app_folder.clone()),
        ("url", dialect.tool("url").unwrap_or_default().to_string()),
        ("port", url_port(dialect).unwrap_or_default()),
    ];
    let launches: Vec<Value> = dialect
        .launches
        .iter()
        .map(|l| fill(&serde_json::to_value(l).unwrap_or(Value::Null), &vars))
        .collect();
    let mut settings = json!({
        // the app appears as its own folder; inside the project, build/ is noise
        "files.exclude": { "build": true },
        "search.exclude": { "build": true },
    });
    for (k, v) in serde_json::to_value(&dialect.editor_settings).ok().and_then(|v| v.as_object().cloned()).unwrap_or_default() {
        settings[k] = v;
    }
    for (k, v) in machine {
        settings[k] = v;
    }
    let mut recommendations = vec!["nuclearlang.nuclearlang".to_string()];
    recommendations.extend(dialect.editor_extensions.iter().cloned());
    let ws = json!({
        "folders": [
            { "name": sources, "path": ".." },
            { "name": app, "path": app_path },
        ],
        "settings": settings,
        "extensions": { "recommendations": recommendations },
        "tasks": { "version": "2.0.0", "tasks": tasks },
        "launch": { "version": "0.2.0", "configurations": launches },
    });
    let path = workspace_path(root, m);
    let text = serde_json::to_string_pretty(&ws).map_err(|e| e.to_string())? + "\n";
    if std::fs::read_to_string(&path).ok().as_deref() != Some(&text) {
        std::fs::create_dir_all(path.parent().unwrap_or(root)).map_err(|e| e.to_string())?;
        std::fs::write(&path, text).map_err(|e| format!("cannot write {}: {e}", path.display()))?;
    }
    Ok(())
}
